fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        // If maxsplit is 0, no splitting occurs
        if maxsplit == 0 {
            result.push(vec![s]);
            continue;
        }
        
        // Use rsplitn for right-split with max splits
        // rsplitn returns an iterator, we collect it into a Vec<String>
        let parts: Vec<String> = s.rsplitn(maxsplit as usize + 1, &sep)
            .map(|part| part.to_string())
            .collect();
        
        // Since rsplitn splits from the right, the parts are in reverse order
        // We need to reverse them to get the correct order
        let mut parts_rev: Vec<String> = parts.into_iter().rev().collect();
        
        // Ensure the result is non-empty (handles empty string case)
        if parts_rev.is_empty() {
            parts_rev.push("".to_string());
        }
        
        result.push(parts_rev);
    }
    
    result
}